    url: merchrouteRuntimeBaseUrl() + '/api/v1/ozon/runtime/jobs/' + encodeURIComponent(String(context.jobId)) + '/transition',
    update: {
      rowVersion: Number(context.rowVersion),
      state: 'MODERATING',
      eventType: 'OZON_FINAL_VERIFICATION_DEFERRED',
      message: '本轮连续读回尚未全部满足，已保存进度并交由两分钟恢复扫描',
      nextAttemptAt: row.nextAttemptAt || row.jobPayload?.imageRecovery?.nextConfirmAt || new Date(now + 10000).toISOString(),
      productMappings: row.productMappings || [],
      storeAlias: String(context.product?.storeAlias || context.storeAlias || ''),
      lastAppliedRevision: Number(context.product?.revision || 0),
      stageStates: row.stageStates || {},
      auditSuppressed: !shouldAudit,
      payload: { ...(row.payload || {}), auditSuppressed: !shouldAudit },
      jobPayload: {
        ...(row.jobPayload || {}),
        finalVerificationLeaseUntil: null,
        lastFinalVerificationReason: row.reason,
        lastFinalVerificationAuditAt: nextAuditAt,
        timings: {
          ...(context.jobPayload?.timings || {}),
          finalVerification: Math.max(0, now - Number(context.verificationStartedAt || now))
        }
      }
    }
  } };
});
